class Solution {
    vector<int> parent;
    vector<int> rank_;

    int find(int i) {
        if (parent[i] != i)
            parent[i] = find(parent[i]);
        return parent[i];
    }

    void union_(int i, int j) {
        int root_i = find(i);
        int root_j = find(j);
        if (root_i != root_j) {
            if (rank_[root_i] > rank_[root_j]) {
                parent[root_j] = root_i;
            } else if (rank_[root_i] < rank_[root_j]) {
                parent[root_i] = root_j;
            } else {
                parent[root_j] = root_i;
                rank_[root_i]++;
            }
        }
    }

public:
    int latestDayToCross(int row, int col, vector<vector<int>>& cells) {
        int N = row * col;
        parent.assign(N + 2, 0);
        rank_.assign(N + 2, 0);
        for (int i = 0; i < N + 2; ++i) {
            parent[i] = i;
        }

        vector<bool> grid(N, false);

        int top = N;
        int bottom = N + 1;

        int dr[] = {-1, 1, 0, 0};
        int dc[] = {0, 0, -1, 1};

        for (int i = N - 1; i >= 0; --i) {
            int r = cells[i][0] - 1;
            int c = cells[i][1] - 1;
            int id = r * col + c;

            grid[id] = true;

            if (r == 0) {
                union_(id, top);
            }
            if (r == row - 1) {
                union_(id, bottom);
            }

            for (int k = 0; k < 4; ++k) {
                int nr = r + dr[k];
                int nc = c + dc[k];
                if (nr >= 0 && nr < row && nc >= 0 && nc < col) {
                    int nid = nr * col + nc;
                    if (grid[nid]) {
                        union_(id, nid);
                    }
                }
            }

            if (find(top) == find(bottom)) {
                return i;
            }
        }

        return -1;
    }
};
